    ...(acceptedPermissions === undefined ? {} : { acceptedPermissions }),
    ...(rateLimitRemaining === undefined ? {} : { rateLimitRemaining }),
    ...(retryAfter === undefined ? {} : { retryAfter }),
    ...(requestId === undefined ? {} : { requestId }),
  };

