      );
    } finally {
      consoleWarn.mockRestore();
    }

    expect(message.retry).toHaveBeenCalledOnce();
    expect(message.ack).not.toHaveBeenCalled();
  });

  it("acknowledges a non-rate-limited forbidden response", async () => {
