    const { env } = createEnv({
      issuer: createGeneratedServiceBinding(),
    });

    await expect(requestGitHubAppInstallationToken(env, { resource, scope })).rejects.toThrow(
      "WORKLOAD_IDENTITY_ISSUER must expose issueToken()",
    );
  });

