import { describe, expect, it } from "vitest";

import type { GitHubIssueCommentStatusReactionJob } from "@cyspbot/github-webhook-jobs";
import {
  acceptGitHubWebhookDelivery,
  type GitHubWebhookReceiverDependencies,
} from "@cyspbot/github-webhook-receiver/github-webhooks/acceptance";
import { githubWebhookHeaders } from "./support/webhook.ts";

interface TestWebhookEnv {
  GITHUB_APP_ID: string;
  GITHUB_WEBHOOK_JOBS: {
    send(
      message: GitHubIssueCommentStatusReactionJob,
      options?: { contentType?: "json" },
    ): Promise<unknown>;
  };
  GITHUB_WEBHOOK_SECRET: string | SecretsStoreSecret;
}

const testWebhookEnv = {
  GITHUB_APP_ID: "000000",
  GITHUB_WEBHOOK_JOBS: {
    send: async () => ({}),
  },
  GITHUB_WEBHOOK_SECRET: "test-webhook-secret",
} satisfies TestWebhookEnv;

describe("webhook delivery acceptance", () => {
  it("acknowledges signed non-ping webhook deliveries without dispatching", async () => {
    const body = JSON.stringify({
      action: "opened",
      issue: {
        number: 12,
      },
    });

    const result = await acceptGitHubWebhookDelivery(
      new Request("https://example.test/github/webhooks", {
        body,
        headers: githubWebhookHeaders(body, "test-webhook-secret", "issues", "delivery-issues"),
        method: "POST",
      }),
      testWebhookEnv,
      testDependencies(),
    );

    expect(result).toEqual({
      body: { accepted: true },
      kind: "accepted",
      status: 202,
    });
  });

  it("accepts signed github ping webhook deliveries", async () => {
    const body = JSON.stringify({
      hook: {
        active: true,
      },
      zen: "Speak like a human.",
    });

    const result = await acceptGitHubWebhookDelivery(
      new Request("https://example.test/github/webhooks", {
        body,
        headers: githubWebhookHeaders(body, "test-webhook-secret", "ping"),
        method: "POST",
      }),
      testWebhookEnv,
      testDependencies(),
    );

    expect(result).toEqual({
      body: { accepted: true, event: "ping" },
      kind: "accepted",
      status: 202,
    });
  });

  it("enqueues a job for a newly created status comment", async () => {
    const jobs: GitHubIssueCommentStatusReactionJob[] = [];
    const body = JSON.stringify({
      action: "created",
      comment: {
        body: "  /cyspbot status  ",
        id: 42,
      },
      repository: {
        name: "cyspbot",
        owner: {
          login: "chikachow",
        },
      },
    });

    const result = await acceptGitHubWebhookDelivery(
      new Request("https://example.test/github/webhooks", {
        body,
        headers: githubWebhookHeaders(body, "test-webhook-secret", "issue_comment", "delivery-job"),
        method: "POST",
      }),
      {
        ...testWebhookEnv,
        GITHUB_WEBHOOK_JOBS: {
          send: async (job) => {
            jobs.push(job);
          },
        },
      },
      testDependencies(),
    );

    expect(result).toEqual({
      body: { accepted: true },
      kind: "accepted",
      status: 202,
    });
    expect(jobs).toEqual([
      {
        commentId: 42,
        deliveryId: "delivery-job",
        kind: "github.issue-comment.status-reaction",
        repository: {
          name: "cyspbot",
          owner: "chikachow",
        },
        version: 1,
      },
    ]);
  });

  it("returns service unavailable when the status job cannot be enqueued", async () => {
    const body = JSON.stringify({
      action: "created",
      comment: {
        body: "/cyspbot status",
        id: 42,
      },
      repository: {
        name: "cyspbot",
        owner: {
          login: "chikachow",
        },
      },
    });

    const result = await acceptGitHubWebhookDelivery(
      new Request("https://example.test/github/webhooks", {
        body,
        headers: githubWebhookHeaders(body, "test-webhook-secret", "issue_comment"),
        method: "POST",
      }),
      {
        ...testWebhookEnv,
        GITHUB_WEBHOOK_JOBS: {
          send: async () => {
            throw new Error("queue unavailable");
          },
        },
      },
      testDependencies(),
    );

    expect(result).toEqual({
      kind: "rejected",
      status: 503,
    });
  });

  it("reads the webhook secret from Cloudflare Secrets Store when bound", async () => {
    const body = JSON.stringify({
      hook: {
        active: true,
      },
      zen: "Speak like a human.",
    });

    const result = await acceptGitHubWebhookDelivery(
      new Request("https://example.test/github/webhooks", {
        body,
        headers: githubWebhookHeaders(body, "test-webhook-secret", "ping"),
        method: "POST",
      }),
      {
        GITHUB_APP_ID: testWebhookEnv.GITHUB_APP_ID,
        GITHUB_WEBHOOK_JOBS: testWebhookEnv.GITHUB_WEBHOOK_JOBS,
        GITHUB_WEBHOOK_SECRET: {
          get: async () => "test-webhook-secret",
        },
      },
      testDependencies(),
    );

    expect(result).toEqual({
      body: { accepted: true, event: "ping" },
      kind: "accepted",
      status: 202,
    });
  });

  it("accepts repeated signed webhook delivery ids", async () => {
    const body = JSON.stringify({
      action: "opened",
    });
    const request = () =>
      new Request("https://example.test/github/webhooks", {
        body,
        headers: githubWebhookHeaders(body, "test-webhook-secret", "issues", "delivery-repeat"),
        method: "POST",
      });

    await expect(
      acceptGitHubWebhookDelivery(request(), testWebhookEnv, testDependencies()),
    ).resolves.toMatchObject({
      kind: "accepted",
      status: 202,
    });

    await expect(
      acceptGitHubWebhookDelivery(request(), testWebhookEnv, testDependencies()),
    ).resolves.toMatchObject({
      kind: "accepted",
      status: 202,
    });
  });

  it("rejects invalid json after authenticating the delivery", async () => {
    const body = "{";

    const result = await acceptGitHubWebhookDelivery(
      new Request("https://example.test/github/webhooks", {
        body,
        headers: githubWebhookHeaders(body, "test-webhook-secret", "issues"),
        method: "POST",
      }),
      testWebhookEnv,
      testDependencies(),
    );

    expect(result).toEqual({
      kind: "rejected",
      status: 400,
    });
  });

  it("rejects invalid signatures", async () => {
    const body = JSON.stringify({
      action: "opened",
    });

    const result = await acceptGitHubWebhookDelivery(
      new Request("https://example.test/github/webhooks", {
        body,
        headers: githubWebhookHeaders(body, "wrong-secret", "issues"),
        method: "POST",
      }),
      testWebhookEnv,
      testDependencies(),
    );

    expect(result).toEqual({
      kind: "rejected",
      status: 401,
    });
  });

  it("rejects oversized streamed bodies without relying on content-length", async () => {
    const body = JSON.stringify({
      payload: "x".repeat(256 * 1024),
    });
    const request = new Request("https://example.test/github/webhooks", {
      body: new Blob([body]).stream(),
      headers: githubWebhookHeaders(body, "test-webhook-secret", "issues"),
      method: "POST",
    });

    expect(request.headers.get("content-length")).toBeNull();

    const result = await acceptGitHubWebhookDelivery(request, testWebhookEnv, testDependencies());

    expect(result).toEqual({
      kind: "rejected",
      status: 413,
    });
  });

  it.each([
    ["missing prefix", "a".repeat(64)],
    ["short digest", `sha256=${"a".repeat(63)}`],
    ["uppercase digest", `sha256=${"A".repeat(64)}`],
    ["non-hex digest", `sha256=${"g".repeat(64)}`],
  ])("rejects malformed signatures: %s", async (_name, signatureHeader) => {
    const body = JSON.stringify({
      action: "opened",
    });
    const headers = {
      ...githubWebhookHeaders(body, "test-webhook-secret", "issues"),
      "x-hub-signature-256": signatureHeader,
    };

    const result = await acceptGitHubWebhookDelivery(
      new Request("https://example.test/github/webhooks", {
        body,
        headers,
        method: "POST",
      }),
      testWebhookEnv,
      testDependencies(),
    );

    expect(result).toEqual({
      kind: "rejected",
      status: 401,
    });
  });

  it("rejects content types whose primary media type is not JSON", async () => {
    const body = JSON.stringify({
      action: "opened",
    });
    const headers = {
      ...githubWebhookHeaders(body, "test-webhook-secret", "issues"),
      "content-type": "text/plain; application/json",
    };

    const result = await acceptGitHubWebhookDelivery(
      new Request("https://example.test/github/webhooks", {
        body,
        headers,
        method: "POST",
      }),
      testWebhookEnv,
      testDependencies(),
    );

    expect(result).toEqual({
      kind: "rejected",
      status: 415,
    });
  });
});

function testDependencies(): GitHubWebhookReceiverDependencies {
  return {
    now: () => new Date("2026-05-24T00:00:00.000Z"),
  };
}
import { describe, expect, it } from "vitest";

import { parseGitHubIssueCommentStatusReactionJob } from "@cyspbot/github-webhook-jobs";

describe("GitHub webhook jobs", () => {
  it("parses the versioned status-reaction job", () => {
    expect(
      parseGitHubIssueCommentStatusReactionJob({
        commentId: 42,
        deliveryId: "delivery-123",
        kind: "github.issue-comment.status-reaction",
        repository: {
          name: "cyspbot",
          owner: "chikachow",
        },
        version: 1,
      }),
    ).toEqual({
      commentId: 42,
      deliveryId: "delivery-123",
      kind: "github.issue-comment.status-reaction",
      repository: {
        name: "cyspbot",
        owner: "chikachow",
      },
      version: 1,
    });
  });

  it.each([
    ["an unknown version", { version: 2 }],
    ["an extra property", { unexpected: true }],
    ["an empty delivery id", { deliveryId: " " }],
    ["a path separator in the repository", { repository: { name: "repo/name", owner: "owner" } }],
    ["a repository fragment", { repository: { name: "repo#name", owner: "owner" } }],
    [
      "a control character in the repository",
      { repository: { name: "repo\u0001name", owner: "owner" } },
    ],
    ["a non-positive comment id", { commentId: 0 }],
  ])("rejects %s", (_name, override) => {
    expect(
      parseGitHubIssueCommentStatusReactionJob({
        commentId: 42,
        deliveryId: "delivery-123",
        kind: "github.issue-comment.status-reaction",
        repository: {
          name: "cyspbot",
          owner: "chikachow",
        },
        version: 1,
        ...override,
      }),
    ).toBeUndefined();
  });
});
import { describe, expect, it } from "vitest";

import { classifyStatusReactionJob } from "../workers/cyspbot-github-webhook-receiver/src/github-webhooks/status-reaction.ts";

const matchingPayload = {
  action: "created",
  comment: {
    body: "/cyspbot status",
    id: 42,
  },
  repository: {
    name: "cyspbot",
    owner: {
      login: "chikachow",
    },
  },
};

describe("GitHub status reaction classification", () => {
  it.each([
    ["a different action", { ...matchingPayload, action: "edited" }],
    ["a different comment", { ...matchingPayload, comment: { body: "/cyspbot help", id: 42 } }],
    ["a missing repository", { ...matchingPayload, repository: null }],
    [
      "an invalid comment id",
      { ...matchingPayload, comment: { ...matchingPayload.comment, id: 0 } },
    ],
    [
      "an invalid repository owner",
      {
        ...matchingPayload,
        repository: { name: "cyspbot", owner: { login: "" } },
      },
    ],
    [
      "an invalid repository name",
      { ...matchingPayload, repository: { name: "", owner: { login: "chikachow" } } },
    ],
  ])("ignores %s", (_name, payload) => {
    expect(classifyStatusReactionJob("issue_comment", "delivery-123", payload)).toBeUndefined();
  });
});
import { createHmac } from "node:crypto";

export const githubWebhookTestSecret = "test-webhook-secret";

const githubWebhookTestAppId = "000000";

export function githubWebhookHeaders(
  body: string,
  secret: string,
  event = "installation_repositories",
  deliveryId = "delivery-123",
  targetId = githubWebhookTestAppId,
): Record<string, string> {
  const signature = createHmac("sha256", secret).update(body).digest("hex");

  return {
    "content-type": "application/json",
    "x-github-delivery": deliveryId,
    "x-github-event": event,
    "x-github-hook-installation-target-id": targetId,
    "x-github-hook-installation-target-type": "integration",
    "x-hub-signature-256": `sha256=${signature}`,
  };
}

