import { describe, expect, it, vi } from "vitest";

import { readBodyUpTo } from "@cyspbot/http/body";

describe("bounded body reading", () => {
  it("accepts an absent body as empty", async () => {
    await expect(readBodyUpTo(null, 0)).resolves.toEqual({
      bytes: new Uint8Array(),
      ok: true,
    });
  });

  it("accepts a body at the exact byte limit", async () => {
    await expect(readBodyUpTo(new Response("abc").body, 3)).resolves.toEqual({
      bytes: new TextEncoder().encode("abc"),
      ok: true,
    });
  });

  it("stops reading and requests cancellation after the byte limit", async () => {
    const cancel = vi.fn();
    let pullCount = 0;
    const body = new ReadableStream<Uint8Array>(
      {
        cancel,
        pull(controller) {
          pullCount += 1;
          controller.enqueue(new Uint8Array(2));
        },
      },
      { highWaterMark: 0 },
    );

    await expect(readBodyUpTo(body, 3)).resolves.toEqual({ ok: false });
    expect(pullCount).toBe(2);
    expect(cancel).toHaveBeenCalledOnce();
  });

  it("does not wait for transport cancellation before rejecting an oversized body", async () => {
    const body = new ReadableStream<Uint8Array>(
      {
        cancel: () => new Promise<void>(() => undefined),
        pull(controller) {
          controller.enqueue(new Uint8Array(2));
        },
      },
      { highWaterMark: 0 },
    );

    await expect(readBodyUpTo(body, 1)).resolves.toEqual({ ok: false });
  });

  it("ignores a rejected best-effort transport cancellation", async () => {
    const body = new ReadableStream<Uint8Array>(
      {
        cancel: () => Promise.reject(new Error("transport cancellation failed")),
        pull(controller) {
          controller.enqueue(new Uint8Array(2));
        },
      },
      { highWaterMark: 0 },
    );

    await expect(readBodyUpTo(body, 1)).resolves.toEqual({ ok: false });
    await Promise.resolve();
  });
});
import { describe, expect, it } from "vitest";

import { readRequestBodyUpTo } from "@cyspbot/http/request-body";

describe("bounded request body reading", () => {
  it("accepts a Content-Length with leading zeroes", async () => {
    const result = await readRequestBodyUpTo(
      new Request("https://example.test", {
        body: "x",
        headers: { "content-length": "0001" },
        method: "POST",
      }),
      1,
    );

    expect(result).toEqual({
      bytes: new TextEncoder().encode("x"),
      ok: true,
    });
  });

  it("rejects an arbitrarily large Content-Length as too large without integer conversion", async () => {
    const result = await readRequestBodyUpTo(
      new Request("https://example.test", {
        body: "x",
        headers: { "content-length": "9".repeat(400) },
        method: "POST",
      }),
      1,
    );

    expect(result).toEqual({ ok: false, status: 413 });
  });

  it.each(["", "+1", "-1", "1.0", "1e3"])(
    "rejects a Content-Length outside the HTTP decimal grammar: %j",
    async (contentLength) => {
      const result = await readRequestBodyUpTo(
        new Request("https://example.test", {
          body: "x",
          headers: { "content-length": contentLength },
          method: "POST",
        }),
        1,
      );

      expect(result).toEqual({ ok: false, status: 400 });
    },
  );
});
