import { readBodyUpTo } from "@cyspbot/http/body";

const tokenExchangeGrantType = "urn:ietf:params:oauth:grant-type:token-exchange";
const requestedTokenType = "urn:ietf:params:oauth:token-type:access_token";
const subjectTokenType = "urn:ietf:params:oauth:token-type:id_token";
const accessTokenScheme = "Bearer";
const maxBrokerResponseBytes = 64 * 1024;
const maxOAuthErrorDescriptionLength = 1024;

export interface GitHubAppInstallationTokenRequest {
  readonly resource: string;
  readonly scope: string;
}

export interface GitHubAppInstallationAccessToken {
  readonly accessToken: string;
  readonly expiresIn: number;
  readonly scope: string;
}

export class GitHubAppTokenBrokerError extends Error {
  readonly status: number;
  readonly oauthErrorCode: string;
  readonly oauthErrorDescription: string | undefined;

  constructor(status: number, oauthErrorCode: string, oauthErrorDescription?: string) {
    super(`GitHub App token broker returned ${status}: ${oauthErrorCode}`);
    this.name = "GitHubAppTokenBrokerError";
    this.status = status;
    this.oauthErrorCode = oauthErrorCode;
    this.oauthErrorDescription = oauthErrorDescription;
  }
}

export interface TokenExchangeEnvironment {
  readonly GITHUB_APP_TOKEN_BROKER: {
    fetch(input: RequestInfo | URL, init?: RequestInit): Promise<Response>;
  };
  readonly GITHUB_APP_TOKEN_BROKER_TOKEN_ENDPOINT: string;
  readonly WORKLOAD_IDENTITY_ISSUER: unknown;
  readonly WORKLOAD_IDENTITY_TOKEN_AUDIENCE: string;
}

interface WorkloadIdentityIssuerBinding {
  issueToken(audience: string): Promise<unknown>;
}

export async function requestGitHubAppInstallationToken(
  env: TokenExchangeEnvironment,
  request: GitHubAppInstallationTokenRequest,
): Promise<GitHubAppInstallationAccessToken> {
  const resource = requireNonEmptyString(request.resource, "resource");
  const scope = requireNonEmptyString(request.scope, "scope");
  const issuer = requireWorkloadIdentityIssuer(env.WORKLOAD_IDENTITY_ISSUER);
  const issuedToken = await issuer.issueToken(env.WORKLOAD_IDENTITY_TOKEN_AUDIENCE);
  const subjectToken = requireIssuedToken(issuedToken);

  const response = await env.GITHUB_APP_TOKEN_BROKER.fetch(
    env.GITHUB_APP_TOKEN_BROKER_TOKEN_ENDPOINT,
    {
      body: new URLSearchParams({
        grant_type: tokenExchangeGrantType,
        requested_token_type: requestedTokenType,
        resource,
        scope,
        subject_token: subjectToken,
        subject_token_type: subjectTokenType,
      }),
      headers: {
        accept: "application/json",
        "content-type": "application/x-www-form-urlencoded",
      },
      method: "POST",
      redirect: "manual",
    },
  );

  if (!response.ok) {
    throw await readBrokerError(response);
  }

  return readInstallationAccessToken(response);
}

function requireWorkloadIdentityIssuer(value: unknown): WorkloadIdentityIssuerBinding {
  if (!isWorkloadIdentityIssuerBinding(value)) {
    throw new TypeError("WORKLOAD_IDENTITY_ISSUER must expose issueToken().");
  }

  return value;
}

function requireIssuedToken(value: unknown): string {
  if (!isRecord(value)) {
    throw new TypeError("WORKLOAD_IDENTITY_ISSUER returned an invalid IssuedToken.");
  }

  return requireNonEmptyString(value["token"], "IssuedToken.token");
}

async function readBrokerError(response: Response): Promise<GitHubAppTokenBrokerError> {
  const body = await readJsonBody(response);

  if (!isRecord(body)) {
    return new GitHubAppTokenBrokerError(response.status, "invalid_response");
  }

  const error = body["error"];
  const descriptionValue = body["error_description"];
  const code = typeof error === "string" && error.length > 0 ? error : "invalid_response";
  const description =
    typeof descriptionValue === "string" &&
    descriptionValue.length > 0 &&
    descriptionValue.length <= maxOAuthErrorDescriptionLength
      ? descriptionValue
      : undefined;

  return new GitHubAppTokenBrokerError(response.status, code, description);
}

async function readInstallationAccessToken(
  response: Response,
): Promise<GitHubAppInstallationAccessToken> {
  const body = await readJsonBody(response);

  if (!isRecord(body)) {
    throw new TypeError("GitHub App token broker returned an invalid token response.");
  }

  const expiresIn = body["expires_in"];
  if (typeof expiresIn !== "number" || !Number.isInteger(expiresIn) || expiresIn <= 0) {
    throw new TypeError("GitHub App token broker returned an invalid expiration.");
  }

  if (body["issued_token_type"] !== requestedTokenType) {
    throw new TypeError("GitHub App token broker returned an invalid issued token type.");
  }

  if (body["token_type"] !== accessTokenScheme) {
    throw new TypeError("GitHub App token broker returned an invalid token type.");
  }

  return {
    accessToken: requireNonEmptyString(body["access_token"], "access_token"),
    expiresIn,
    scope: requireNonEmptyString(body["scope"], "scope"),
  };
}

async function readJsonBody(response: Response): Promise<unknown> {
  const body = await readBodyUpTo(response.body, maxBrokerResponseBytes);

  if (!body.ok) {
    return undefined;
  }

  try {
    return JSON.parse(new TextDecoder().decode(body.bytes));
  } catch {
    return undefined;
  }
}

function isWorkloadIdentityIssuerBinding(value: unknown): value is WorkloadIdentityIssuerBinding {
  return isRecord(value) && typeof value["issueToken"] === "function";
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function requireNonEmptyString(value: unknown, name: string): string {
  if (typeof value !== "string" || value.trim().length === 0) {
    throw new TypeError(`${name} must be a non-empty string.`);
  }

  return value;
}
import { readBodyUpTo } from "@cyspbot/http/body";
import type { GitHubIssueCommentStatusReactionJob } from "@cyspbot/github-webhook-jobs";
import {
  requestGitHubAppInstallationToken,
  type TokenExchangeEnvironment,
} from "@cyspbot/token-exchange";

const githubApiBaseUrl = "https://api.github.com";
const githubApiVersion = "2022-11-28";
const githubUserAgent = "cyspbot-github-webhook-processor";
const reactionContent = "eyes";
const reactionScope = "issues:write pull_requests:write";
const maxGitHubReactionErrorBodyBytes = 16 * 1024;
const maxGitHubReactionDiagnosticValueLength = 1024;

export interface GitHubReactionErrorDiagnostics {
  readonly acceptedPermissions?: string | undefined;
  readonly documentationUrl?: string | undefined;
  readonly message?: string | undefined;
  readonly rateLimitRemaining?: string | undefined;
  readonly requestId?: string | undefined;
  readonly retryAfter?: string | undefined;
}

export interface GitHubReactionDependencies {
  fetch(input: RequestInfo | URL, init?: RequestInit): Promise<Response>;
}

export class GitHubReactionError extends Error {
  readonly diagnostics: GitHubReactionErrorDiagnostics;
  readonly rateLimited: boolean;
  readonly retryable: boolean;
  readonly status: number;

  constructor(
    status: number,
    rateLimited: boolean,
    diagnostics: GitHubReactionErrorDiagnostics = {},
  ) {
    super(`GitHub reaction request returned ${status}.`);
    this.name = "GitHubReactionError";
    this.diagnostics = diagnostics;
    this.rateLimited = rateLimited;
    this.retryable = status === 429 || status >= 500 || rateLimited;
    this.status = status;
  }
}

export async function addStatusReaction(
  env: TokenExchangeEnvironment,
  job: GitHubIssueCommentStatusReactionJob,
  dependencies: GitHubReactionDependencies,
): Promise<void> {
  const repositoryPath = `${encodeURIComponent(job.repository.owner)}/${encodeURIComponent(job.repository.name)}`;
  const resource = `${githubApiBaseUrl}/repos/${repositoryPath}`;
  const token = await requestGitHubAppInstallationToken(env, {
    resource,
    scope: reactionScope,
  });

  const response = await dependencies.fetch(
    `${resource}/issues/comments/${job.commentId}/reactions`,
    {
      body: JSON.stringify({ content: reactionContent }),
      headers: {
        accept: "application/vnd.github+json",
        authorization: `Bearer ${token.accessToken}`,
        "content-type": "application/json",
        "user-agent": githubUserAgent,
        "x-github-api-version": githubApiVersion,
      },
      method: "POST",
    },
  );

  if (response.status !== 200 && response.status !== 201) {
    const diagnostics = await readGitHubReactionErrorDiagnostics(response);

    throw new GitHubReactionError(
      response.status,
      response.status === 403 &&
        (response.headers.get("retry-after") !== null ||
          response.headers.get("x-ratelimit-remaining") === "0"),
      diagnostics,
    );
  }

  await response.body?.cancel();
}

async function readGitHubReactionErrorDiagnostics(
  response: Response,
): Promise<GitHubReactionErrorDiagnostics> {
  const acceptedPermissions = boundedHeaderValue(response, "x-accepted-github-permissions");
  const rateLimitRemaining = boundedHeaderValue(response, "x-ratelimit-remaining");
  const retryAfter = boundedHeaderValue(response, "retry-after");
  const requestId = boundedHeaderValue(response, "x-github-request-id");
  const headerDiagnostics = {
    ...(acceptedPermissions === undefined ? {} : { acceptedPermissions }),
    ...(rateLimitRemaining === undefined ? {} : { rateLimitRemaining }),
    ...(retryAfter === undefined ? {} : { retryAfter }),
    ...(requestId === undefined ? {} : { requestId }),
  };

  let body: Awaited<ReturnType<typeof readBodyUpTo>>;
  try {
    body = await readBodyUpTo(response.body, maxGitHubReactionErrorBodyBytes);
  } catch {
    return headerDiagnostics;
  }

  if (!body.ok) {
    return headerDiagnostics;
  }

  let value: unknown;
  try {
    value = JSON.parse(new TextDecoder().decode(body.bytes));
  } catch {
    return headerDiagnostics;
  }

  if (!isRecord(value)) {
    return headerDiagnostics;
  }

  const message = boundedString(value["message"]);
  const documentationUrl = boundedString(value["documentation_url"]);

  return {
    ...headerDiagnostics,
    ...(message === undefined ? {} : { message }),
    ...(documentationUrl === undefined ? {} : { documentationUrl }),
  };
}

function boundedHeaderValue(response: Response, name: string): string | undefined {
  return boundedString(response.headers.get(name));
}

function boundedString(value: unknown): string | undefined {
  if (typeof value !== "string" || value.length === 0) {
    return undefined;
  }

  return value.slice(0, maxGitHubReactionDiagnosticValueLength);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
import { parseGitHubIssueCommentStatusReactionJob } from "@cyspbot/github-webhook-jobs";
import { GitHubAppTokenBrokerError } from "@cyspbot/token-exchange";
import {
  addStatusReaction,
  GitHubReactionError,
  type GitHubReactionDependencies,
} from "./github/reactions.ts";

const defaultDependencies: GitHubReactionDependencies = {
  fetch: (input, init) => globalThis.fetch(input, init),
};

export function createGitHubWebhookProcessorWorker(
  dependencies: GitHubReactionDependencies = defaultDependencies,
): ExportedHandler<GitHubWebhookProcessorEnv, unknown> {
  return {
    async queue(batch, env) {
      for (const message of batch.messages) {
        const job = parseGitHubIssueCommentStatusReactionJob(message.body);

        if (job === undefined) {
          console.warn("github_webhook_job_rejected", {
            attempts: message.attempts,
            messageId: message.id,
            queue: batch.queue,
            reason: "invalid_job",
          });
          message.ack();
          continue;
        }

        try {
          await addStatusReaction(env, job, dependencies);
          message.ack();
        } catch (error) {
          if (shouldRetry(error)) {
            console.warn("github_webhook_job_retrying", {
              attempts: message.attempts,
              error: errorName(error),
              ...errorLogFields(error),
              messageId: message.id,
              queue: batch.queue,
              status: errorStatus(error),
            });
            message.retry();
          } else {
            console.error("github_webhook_job_failed", {
              attempts: message.attempts,
              error: errorName(error),
              ...errorLogFields(error),
              messageId: message.id,
              queue: batch.queue,
              status: errorStatus(error),
            });
            message.ack();
          }
        }
      }
    },
  };
}

function shouldRetry(error: unknown): boolean {
  if (error instanceof GitHubReactionError) {
    return error.retryable;
  }

  if (error instanceof GitHubAppTokenBrokerError) {
    return error.status === 429 || error.status >= 500;
  }

  return true;
}

function errorName(error: unknown): string {
  if (error instanceof Error) {
    return error.name;
  }

  return typeof error;
}

function errorStatus(error: unknown): number | undefined {
  if (error instanceof GitHubReactionError || error instanceof GitHubAppTokenBrokerError) {
    return error.status;
  }

  return undefined;
}

function errorLogFields(error: unknown): Record<string, unknown> {
  if (error instanceof GitHubReactionError) {
    return { github: error.diagnostics };
  }

  return {};
}

